module Alu(
  input  [4:0]  op,
  input  [31:0] decoded_pc,
                decoded_imm,
  input  [2:0]  decoded_branchOp,
  input         decoded_isJal,
                decoded_isJalr,
  input  [31:0] a,
                b,
  output [31:0] result,
                link,
  output        branchTaken,
  output [31:0] target
);

  wire [62:0] _result_T_4 = {31'h0, a} << b[4:0];
  wire        lessU = a < b;
  wire [31:0] _GEN = {27'h0, b[4:0]};
  reg         casez_tmp;
  wire        _branchTaken_T_4 = decoded_branchOp == 3'h0 & a == b;
  always_comb begin
    casez (decoded_branchOp)
      3'b000:
        casez_tmp = _branchTaken_T_4;
      3'b001:
        casez_tmp = a != b;
      3'b010:
        casez_tmp = $signed(a) < $signed(b);
      3'b011:
        casez_tmp = $signed(a) >= $signed(b);
      3'b100:
        casez_tmp = lessU;
      3'b101:
        casez_tmp = a >= b;
      3'b110:
        casez_tmp = _branchTaken_T_4;
      default:
        casez_tmp = _branchTaken_T_4;
    endcase
  end // always_comb
  wire [31:0] _registerTarget_T = a + decoded_imm;
  assign result =
    op == 5'h9
      ? a & b
      : op == 5'h8
          ? a | b
          : op == 5'h7
              ? $signed($signed(a) >>> _GEN)
              : op == 5'h6
                  ? a >> _GEN
                  : op == 5'h5
                      ? a ^ b
                      : op == 5'h4
                          ? {31'h0, lessU}
                          : op == 5'h3
                              ? {31'h0, $signed(a) < $signed(b)}
                              : op == 5'h2
                                  ? _result_T_4[31:0]
                                  : op == 5'h1 ? a - b : op == 5'h0 ? a + b : 32'h0;
  assign link = decoded_pc + 32'h4;
  assign branchTaken = casez_tmp | decoded_isJal | decoded_isJalr;
  assign target =
    decoded_isJalr ? {_registerTarget_T[31:1], 1'h0} : decoded_pc + decoded_imm;
endmodule

