      pendingStoreLine_6 <= pendingStoreWord == 4'h6 ? merged : _lineSram_rdata[223:192];
      pendingStoreLine_7 <= pendingStoreWord == 4'h7 ? merged : _lineSram_rdata[255:224];
      pendingStoreLine_8 <= pendingStoreWord == 4'h8 ? merged : _lineSram_rdata[287:256];
      pendingStoreLine_9 <= pendingStoreWord == 4'h9 ? merged : _lineSram_rdata[319:288];
      pendingStoreLine_10 <= pendingStoreWord == 4'hA ? merged : _lineSram_rdata[351:320];
      pendingStoreLine_11 <= pendingStoreWord == 4'hB ? merged : _lineSram_rdata[383:352];
      pendingStoreLine_12 <= pendingStoreWord == 4'hC ? merged : _lineSram_rdata[415:384];
      pendingStoreLine_13 <= pendingStoreWord == 4'hD ? merged : _lineSram_rdata[447:416];
      pendingStoreLine_14 <= pendingStoreWord == 4'hE ? merged : _lineSram_rdata[479:448];
      pendingStoreLine_15 <= (&pendingStoreWord) ? merged : _lineSram_rdata[511:480];
    end
    if (_lineSram_addr_T_9)
      loadResponseData <= (&requestedIndex) ? fillLineData_15 : requestedData;
    else if (_GEN_2)
      loadResponseData <= casez_tmp_7;
  end // always @(posedge)
  sram_fakeram #(
    .DEPTH(64),
    .WIDTH(512),
    .WRITE_GRANULARITY(512)
  ) lineSram (
    .clk   (clock),
    .en
      (_lineSram_addr_T_3 | _lineSram_addr_T_5 | _lineSram_addr_T_9
       | _lineSram_wdata_T_30),
    .we    (_lineSram_addr_T_9 | _lineSram_wdata_T_30),
    .wmask (1'h1),
    .addr
      (_lineSram_addr_T_9
         ? {fillSet, 1'h0} + {5'h0, fillWay}
         : _lineSram_wdata_T_30 | _lineSram_addr_T_5
             ? pendingStoreSramAddr
             : _lineSram_addr_T_3 ? pendingLoadSramAddr : 6'h0),
    .wdata
      ({_lineSram_wdata_T_30 ? pendingStoreLine_15 : fillLineData_15,
        _lineSram_wdata_T_30 ? pendingStoreLine_14 : fillLineData_14,
        _lineSram_wdata_T_30 ? pendingStoreLine_13 : fillLineData_13,
        _lineSram_wdata_T_30 ? pendingStoreLine_12 : fillLineData_12,
        _lineSram_wdata_T_30 ? pendingStoreLine_11 : fillLineData_11,
        _lineSram_wdata_T_30 ? pendingStoreLine_10 : fillLineData_10,
        _lineSram_wdata_T_30 ? pendingStoreLine_9 : fillLineData_9,
        _lineSram_wdata_T_30 ? pendingStoreLine_8 : fillLineData_8,
        _lineSram_wdata_T_30 ? pendingStoreLine_7 : fillLineData_7,
        _lineSram_wdata_T_30 ? pendingStoreLine_6 : fillLineData_6,
        _lineSram_wdata_T_30 ? pendingStoreLine_5 : fillLineData_5,
        _lineSram_wdata_T_30 ? pendingStoreLine_4 : fillLineData_4,
        _lineSram_wdata_T_30 ? pendingStoreLine_3 : fillLineData_3,
        _lineSram_wdata_T_30 ? pendingStoreLine_2 : fillLineData_2,
        _lineSram_wdata_T_30 ? pendingStoreLine_1 : fillLineData_1,
        _lineSram_wdata_T_30 ? pendingStoreLine_0 : fillLineData_0}),
    .rdata (_lineSram_rdata)
  );
  Queue8_StoreRequest writeQueue (
    .clock              (clock),
    .reset              (reset),
    .io_enq_ready       (_writeQueue_io_enq_ready),
    .io_enq_valid       (writeQueue_io_enq_valid),
    .io_enq_bits_addr   (storeReq_bits_addr),
    .io_enq_bits_data   (storeReq_bits_data),
    .io_enq_bits_strobe (storeReq_bits_strobe),
    .io_enq_bits_isExit (storeReq_bits_isExit),
    .io_deq_ready       (writeReq_ready),
    .io_deq_valid       (writeReq_valid),
    .io_deq_bits_addr   (writeReq_bits_addr),
    .io_deq_bits_data   (writeReq_bits_data),
    .io_deq_bits_strobe (writeReq_bits_strobe),
    .io_deq_bits_isExit (writeReq_bits_isExit),
    .io_count           (_writeQueue_io_count)
  );
  assign loadReq_ready = loadReq_ready_0;
  assign loadResp_valid = loadResponseValid;
  assign loadResp_bits = loadResponseData;
  assign storeReq_ready = storeReq_ready_0;
  assign storeResp_valid = storeResponse_valid;
  assign memReq_valid = memReq_valid_0;
  assign memReq_bits = fillAddress;
endmodule

module AxiReadArbiter(
  input         clock,
                reset,
  output        iReq_ready,
  input         iReq_valid,
  input  [31:0] iReq_bits,
  output        iResp_valid,
  output [31:0] iResp_bits,
  output        dReq_ready,
  input         dReq_valid,
  input  [31:0] dReq_bits,
  output        dResp_valid,
  output [31:0] dResp_bits,
                araddr,
  output        arvalid,
  input         arready,
  input  [31:0] rdata,
  input         rvalid,
  output        rready
);

  reg  [1:0]  state;
  reg         lastWasI;
  reg  [31:0] addressReg;
  reg         selectedI;
  wire        chooseI = iReq_valid & (~lastWasI | ~dReq_valid);
  wire        _dReq_ready_T = state == 2'h0;
  wire        _arvalid_T = state == 2'h1;
  wire        _rready_T = state == 2'h2;
  wire        _GEN = _rready_T & rvalid;
  wire        _GEN_0 = _dReq_ready_T | _arvalid_T;
  wire        _GEN_1 = iReq_valid | dReq_valid;
  wire        _GEN_2 = _dReq_ready_T & _GEN_1;
  always @(posedge clock) begin
    if (reset) begin
      state <= 2'h0;
      lastWasI <= 1'h0;
    end
    else begin
      if (_dReq_ready_T) begin
        if (_GEN_1)
          state <= 2'h1;
      end
      else if (_arvalid_T) begin
        if (arready)
          state <= 2'h2;
      end
      else if (_GEN)
        state <= 2'h0;
      if (_GEN_2)
        lastWasI <= chooseI;
    end
    if (_GEN_2) begin
      addressReg <= {chooseI ? iReq_bits[31:2] : dReq_bits[31:2], 2'h0};
      selectedI <= chooseI;
    end
  end // always @(posedge)
  assign iReq_ready = _dReq_ready_T & chooseI;
  assign iResp_valid = ~_GEN_0 & _GEN & selectedI;
  assign iResp_bits = _GEN_0 | ~(_rready_T & rvalid & selectedI) ? 32'h0 : rdata;
  assign dReq_ready = _dReq_ready_T & ~chooseI & dReq_valid;
  assign dResp_valid = ~_GEN_0 & _GEN & ~selectedI;
  assign dResp_bits = _GEN_0 | ~_GEN | selectedI ? 32'h0 : rdata;
  assign araddr = addressReg;
  assign arvalid = _arvalid_T;
  assign rready = _rready_T;
endmodule

module AxiWriteEngine(
  input         clock,
                reset,
  output        req_ready,
  input         req_valid,
  input  [31:0] req_bits_addr,
                req_bits_data,
  input  [3:0]  req_bits_strobe,
  input         req_bits_isExit,
  output        resp_valid,
                resp_bits_isExit,
                idle,
  output [31:0] awaddr,
  output        awvalid,
  input         awready,
  output [31:0] wdata,
  output [3:0]  wstrb,
  output        wvalid,
  input         wready,
                bvalid,
  output        bready
);

  reg  [1:0]  state;
  reg  [31:0] request_addr;
  reg  [31:0] request_data;
  reg  [3:0]  request_strobe;
  reg         request_isExit;
  reg         awDone;
  reg         wDone;
  wire        req_ready_0 = state == 2'h0;
  wire        _wvalid_T = state == 2'h1;
  wire        _awvalid_output = _wvalid_T & ~awDone;
  wire        _wvalid_output = _wvalid_T & ~wDone;
  wire        _bready_T = state == 2'h2;
  wire        _GEN = req_ready_0 | _wvalid_T;
  wire        _GEN_0 = _bready_T & bvalid;
  wire        _GEN_1 = _awvalid_output & awready;
  wire        _GEN_2 = _wvalid_output & wready;
  wire        _GEN_3 = req_ready_0 & req_valid;
  always @(posedge clock) begin
    if (reset) begin
      state <= 2'h0;
      awDone <= 1'h0;
      wDone <= 1'h0;
    end
    else begin
      if (req_ready_0) begin
        if (_GEN_3)
          state <= 2'h1;
      end
      else if (_wvalid_T) begin
        if ((awDone | _GEN_1) & (wDone | _GEN_2))
          state <= 2'h2;
      end
      else if (_GEN_0)
        state <= 2'h0;
      awDone <= req_ready_0 ? ~_GEN_3 & awDone : _GEN_1 | awDone;
      wDone <= req_ready_0 ? ~_GEN_3 & wDone : _GEN_2 | wDone;
    end
    if (_GEN_3) begin
      request_addr <= req_bits_addr;
      request_data <= req_bits_data;
      request_strobe <= req_bits_strobe;
      request_isExit <= req_bits_isExit;
    end
  end // always @(posedge)
  assign req_ready = req_ready_0;
  assign resp_valid = ~_GEN & _bready_T & bvalid;
  assign resp_bits_isExit = ~_GEN & _GEN_0 & request_isExit;
  assign idle = req_ready_0;
  assign awaddr = request_addr;
  assign awvalid = _awvalid_output;
  assign wdata = request_data;
  assign wstrb = request_strobe;
  assign wvalid = _wvalid_output;
  assign bready = _bready_T;
endmodule

