    .storeReq_bits_data    (dStoreReq_bits_data),
    .storeReq_bits_strobe  (dStoreReq_bits_strobe),
    .storeReq_bits_isExit  (dStoreReq_bits_isExit),
    .storeResp_valid       (dStoreResp_valid),
    .memReq_ready          (_reads_dReq_ready),
    .memReq_valid          (_dcache_memReq_valid),
    .memReq_bits           (_dcache_memReq_bits),
    .memResp_valid         (_reads_dResp_valid),
    .memResp_bits          (_reads_dResp_bits),
    .writeReq_ready        (_writes_req_ready),
    .writeReq_valid        (_dcache_writeReq_valid),
    .writeReq_bits_addr    (_dcache_writeReq_bits_addr),
    .writeReq_bits_data    (_dcache_writeReq_bits_data),
    .writeReq_bits_strobe  (_dcache_writeReq_bits_strobe),
    .writeReq_bits_isExit  (_dcache_writeReq_bits_isExit),
    .writeResp_valid       (_writes_resp_valid),
    .writeResp_bits_isExit (_writes_resp_bits_isExit),
    .writeIdle             (_writes_idle)
  );
  AxiReadArbiter reads (
    .clock       (clock),
    .reset       (reset),
    .iReq_ready  (_reads_iReq_ready),
    .iReq_valid  (_icache_memReq_valid),
    .iReq_bits   (_icache_memReq_bits),
    .iResp_valid (_reads_iResp_valid),
    .iResp_bits  (_reads_iResp_bits),
    .dReq_ready  (_reads_dReq_ready),
    .dReq_valid  (_dcache_memReq_valid),
    .dReq_bits   (_dcache_memReq_bits),
    .dResp_valid (_reads_dResp_valid),
    .dResp_bits  (_reads_dResp_bits),
    .araddr      (araddr),
    .arvalid     (arvalid),
    .arready     (arready),
    .rdata       (rdata),
    .rvalid      (rvalid),
    .rready      (rready)
