  AxiWriteEngine writes (
    .clock            (clock),
    .reset            (reset),
    .req_ready        (_writes_req_ready),
    .req_valid        (_dcache_writeReq_valid),
    .req_bits_addr    (_dcache_writeReq_bits_addr),
    .req_bits_data    (_dcache_writeReq_bits_data),
    .req_bits_strobe  (_dcache_writeReq_bits_strobe),
    .req_bits_isExit  (_dcache_writeReq_bits_isExit),
    .resp_valid       (_writes_resp_valid),
    .resp_bits_isExit (_writes_resp_bits_isExit),
    .idle             (_writes_idle),
    .awaddr           (awaddr),
    .awvalid          (awvalid),
    .awready          (awready),
    .wdata            (wdata),
    .wstrb            (wstrb),
    .wvalid           (wvalid),
    .wready           (wready),
    .bvalid           (bvalid),
    .bready           (bready)
  );
